files.content:
body {
  display: grid;
  place-items: center;
  box-sizing: border-box;
  min-block-size: 100dvb;
  margin: 0;
  padding: 20px;
  font-family: 'PT Sans', sans-serif;
  background-color: skyblue;
  background-image:
    image-set(
      url(https://code.s3.yandex.net/frontend-developer/fullstack-developer/sprint3/fish.avif) type("image/avif"),
      url(https://code.s3.yandex.net/frontend-developer/fullstack-developer/sprint3/fish.webp) type("image/webp"),
      url(https://code.s3.yandex.net/frontend-developer/fullstack-developer/sprint3/fish.png) type("image/png")
    ),
    image-set(
      url(https://code.s3.yandex.net/frontend-developer/fullstack-developer/sprint3/water.avif) type("image/avif"),
      url(https://code.s3.yandex.net/frontend-developer/fullstack-developer/sprint3/water.webp) type("image/webp"),
      url(https://code.s3.yandex.net/frontend-developer/fullstack-developer/sprint3/water.jpg) type("image/jpeg")
    );
  background-repeat: no-repeat;
  background-position: 10% 90%, center;
  background-size: 200px, cover;
}

h1 {
  margin: 0;
  padding: 10px;
  font-weight: normal;
  font-size: 60px;
  line-height: 1;
  text-align: center;
  text-transform: uppercase;
  background-color: #fff;
}
